import{_ as a}from"./plugin-vue_export-helper-c27b6911.js";import{o as t,c as p,d as o,a as n,b as s,f as e}from"./app-49128265.js";const c={},l=n("p",null,[s('很多人对编译器的第一印象是"很玄"。但拆开看，它的第一步——'),n("strong",null,"词法分析"),s("——其实朴素得不能再朴素："),n("strong",null,'把一长串字符，切成一个个有意义的"词"。'),s(" 这篇就把这一步彻底讲透，顺便聊几个初学时最容易栽的坑。")],-1),u=n("blockquote",null,[n("p",null,"本文用一个迷你 DSL 的例子，代码全部自写、可运行，不涉及任何专有项目。")],-1),i=e(`<h2 id="一、先建立直觉-读句子的两步" tabindex="-1"><a class="header-anchor" href="#一、先建立直觉-读句子的两步" aria-hidden="true">#</a> 一、先建立直觉：读句子的两步</h2><p>你读&quot;小明 吃 苹果&quot;这句话，大脑其实分两步：</p><ol><li><strong>认词</strong>：先把字符切成 <code>小明</code>/<code>吃</code>/<code>苹果</code>，并知道各自是名词、动词、名词——但<strong>不管这句话通不通顺</strong>。</li><li><strong>组句</strong>：再把这些词按主谓宾组织起来，判断合不合法。</li></ol><p>编译器一模一样：</p><ul><li><strong>第一步「认词」= 词法分析（Lexer）</strong>：字符流 → 一个个 token。</li><li><strong>第二步「组句」= 语法分析（Parser）</strong>：token 流 → 一棵结构树（AST）。</li></ul><p>本文只讲第一步。记住这条边界——<strong>很多困惑都来自把这两步混在一起</strong>。</p><h2 id="二、一个迷你-dsl" tabindex="-1"><a class="header-anchor" href="#二、一个迷你-dsl" aria-hidden="true">#</a> 二、一个迷你 DSL</h2><p>假设我们要给一个&quot;规则过滤&quot;DSL 写解析器，它长这样：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>age &gt;= 18 and active == &quot;true&quot;
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>我们的目标：把这串字符切成 token 序列：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>IDENT(age)  GE(&gt;=)  NUMBER(18)  AND(and)  IDENT(active)  EQ(==)  STRING(true)  EOF
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>注意几个点先剧透：<code>&gt;=</code> 是<strong>一个</strong> token 不是两个；<code>and</code> 是<strong>关键字</strong>不是普通名字；<code>&quot;true&quot;</code> 切出来的值是 <code>true</code>（<strong>没有引号</strong>）；末尾那个 <code>EOF</code> 是我们<strong>自己补的</strong>。下面逐一解释。</p><h2 id="三、token-长什么样" tabindex="-1"><a class="header-anchor" href="#三、token-长什么样" aria-hidden="true">#</a> 三、token 长什么样</h2><p>每个 token 我们用三元组表示：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">enum</span> <span class="token class-name">Type</span> <span class="token punctuation">{</span> <span class="token constant">IDENT</span><span class="token punctuation">,</span> <span class="token constant">NUMBER</span><span class="token punctuation">,</span> <span class="token constant">STRING</span><span class="token punctuation">,</span> <span class="token constant">GE</span><span class="token punctuation">,</span> <span class="token constant">LE</span><span class="token punctuation">,</span> <span class="token constant">EQ</span><span class="token punctuation">,</span> <span class="token constant">AND</span><span class="token punctuation">,</span> <span class="token constant">OR</span><span class="token punctuation">,</span> <span class="token constant">LPAREN</span><span class="token punctuation">,</span> <span class="token constant">RPAREN</span><span class="token punctuation">,</span> <span class="token constant">EOF</span> <span class="token punctuation">}</span>

<span class="token keyword">record</span> <span class="token class-name">Token</span><span class="token punctuation">(</span><span class="token class-name">Type</span> type<span class="token punctuation">,</span> <span class="token class-name">String</span> value<span class="token punctuation">,</span> <span class="token keyword">int</span> pos<span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>type</code>：<strong>类别</strong>，给后面的 parser 用——它判断语法时只看 type。</li><li><code>value</code>：token 在原文里的内容。</li><li><code>pos</code>：位置，<strong>报错时用</strong>（&quot;第 12 个字符附近出错&quot;）。</li></ul><p>⚠️ 第一个坑：<strong><code>(type, value, pos)</code> 不是铁律，只是一种设计</strong>。真正必须的只有 <code>type</code>；<code>value</code>、位置信息（单偏移 / 行列 / 区间）都因实现而异。</p><h2 id="四、核心-一个从左扫到右的循环" tabindex="-1"><a class="header-anchor" href="#四、核心-一个从左扫到右的循环" aria-hidden="true">#</a> 四、核心：一个从左扫到右的循环</h2><p>词法分析器机械上就是一个 <code>while</code>，从头扫到<strong>整段文本</strong>的末尾，每圈吐一个 token：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Token</span><span class="token punctuation">&gt;</span></span> <span class="token function">tokenize</span><span class="token punctuation">(</span><span class="token class-name">String</span> input<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Token</span><span class="token punctuation">&gt;</span></span> tokens <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">ArrayList</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">int</span> pos <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span>
    <span class="token keyword">while</span> <span class="token punctuation">(</span>pos <span class="token operator">&lt;</span> input<span class="token punctuation">.</span><span class="token function">length</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// 1) 先跳过空白</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name">Character</span><span class="token punctuation">.</span><span class="token function">isWhitespace</span><span class="token punctuation">(</span>input<span class="token punctuation">.</span><span class="token function">charAt</span><span class="token punctuation">(</span>pos<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> pos<span class="token operator">++</span><span class="token punctuation">;</span> <span class="token keyword">continue</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>

        <span class="token keyword">char</span> c <span class="token operator">=</span> input<span class="token punctuation">.</span><span class="token function">charAt</span><span class="token punctuation">(</span>pos<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token comment">// 2) 多字符运算符：要&quot;向前看&quot;</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span>c <span class="token operator">==</span> <span class="token char">&#39;&gt;&#39;</span> <span class="token operator">&amp;&amp;</span> <span class="token function">peek</span><span class="token punctuation">(</span>input<span class="token punctuation">,</span> pos <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token char">&#39;=&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> tokens<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Token</span><span class="token punctuation">(</span><span class="token class-name">Type</span><span class="token punctuation">.</span><span class="token constant">GE</span><span class="token punctuation">,</span> <span class="token string">&quot;&gt;=&quot;</span><span class="token punctuation">,</span> pos<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> pos <span class="token operator">+=</span> <span class="token number">2</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
        <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>c <span class="token operator">==</span> <span class="token char">&#39;&lt;&#39;</span> <span class="token operator">&amp;&amp;</span> <span class="token function">peek</span><span class="token punctuation">(</span>input<span class="token punctuation">,</span> pos <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token char">&#39;=&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> tokens<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Token</span><span class="token punctuation">(</span><span class="token class-name">Type</span><span class="token punctuation">.</span><span class="token constant">LE</span><span class="token punctuation">,</span> <span class="token string">&quot;&lt;=&quot;</span><span class="token punctuation">,</span> pos<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> pos <span class="token operator">+=</span> <span class="token number">2</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
        <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>c <span class="token operator">==</span> <span class="token char">&#39;=&#39;</span> <span class="token operator">&amp;&amp;</span> <span class="token function">peek</span><span class="token punctuation">(</span>input<span class="token punctuation">,</span> pos <span class="token operator">+</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token char">&#39;=&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> tokens<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Token</span><span class="token punctuation">(</span><span class="token class-name">Type</span><span class="token punctuation">.</span><span class="token constant">EQ</span><span class="token punctuation">,</span> <span class="token string">&quot;==&quot;</span><span class="token punctuation">,</span> pos<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> pos <span class="token operator">+=</span> <span class="token number">2</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
        <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>c <span class="token operator">==</span> <span class="token char">&#39;(&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> tokens<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Token</span><span class="token punctuation">(</span><span class="token class-name">Type</span><span class="token punctuation">.</span><span class="token constant">LPAREN</span><span class="token punctuation">,</span> <span class="token string">&quot;(&quot;</span><span class="token punctuation">,</span> pos<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> pos<span class="token operator">++</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
        <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>c <span class="token operator">==</span> <span class="token char">&#39;)&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> tokens<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Token</span><span class="token punctuation">(</span><span class="token class-name">Type</span><span class="token punctuation">.</span><span class="token constant">RPAREN</span><span class="token punctuation">,</span> <span class="token string">&quot;)&quot;</span><span class="token punctuation">,</span> pos<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> pos<span class="token operator">++</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
        <span class="token comment">// 3) 变长 token：字符串、数字、标识符/关键字</span>
        <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span>c <span class="token operator">==</span> <span class="token char">&#39;&quot;&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> pos <span class="token operator">=</span> <span class="token function">readString</span><span class="token punctuation">(</span>input<span class="token punctuation">,</span> pos<span class="token punctuation">,</span> tokens<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
        <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name">Character</span><span class="token punctuation">.</span><span class="token function">isDigit</span><span class="token punctuation">(</span>c<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> pos <span class="token operator">=</span> <span class="token function">readNumber</span><span class="token punctuation">(</span>input<span class="token punctuation">,</span> pos<span class="token punctuation">,</span> tokens<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
        <span class="token keyword">else</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token class-name">Character</span><span class="token punctuation">.</span><span class="token function">isLetter</span><span class="token punctuation">(</span>c<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> pos <span class="token operator">=</span> <span class="token function">readWord</span><span class="token punctuation">(</span>input<span class="token punctuation">,</span> pos<span class="token punctuation">,</span> tokens<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
        <span class="token keyword">else</span> <span class="token punctuation">{</span> pos<span class="token operator">++</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> <span class="token comment">// 不认识的字符：跳过（容错）</span>
    <span class="token punctuation">}</span>
    tokens<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Token</span><span class="token punctuation">(</span><span class="token class-name">Type</span><span class="token punctuation">.</span><span class="token constant">EOF</span><span class="token punctuation">,</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">,</span> pos<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// 4) 自己补上结束哨兵</span>
    <span class="token keyword">return</span> tokens<span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">char</span> <span class="token function">peek</span><span class="token punctuation">(</span><span class="token class-name">String</span> s<span class="token punctuation">,</span> <span class="token keyword">int</span> i<span class="token punctuation">)</span> <span class="token punctuation">{</span> <span class="token keyword">return</span> i <span class="token operator">&lt;</span> s<span class="token punctuation">.</span><span class="token function">length</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">?</span> s<span class="token punctuation">.</span><span class="token function">charAt</span><span class="token punctuation">(</span>i<span class="token punctuation">)</span> <span class="token operator">:</span> <span class="token char">&#39;\\0&#39;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这段代码里藏着词法分析的全部精髓，下面挑四个&quot;魔鬼细节&quot;。</p><h2 id="五、四个魔鬼细节-也是面试最爱问的" tabindex="-1"><a class="header-anchor" href="#五、四个魔鬼细节-也是面试最爱问的" aria-hidden="true">#</a> 五、四个魔鬼细节（也是面试最爱问的）</h2><h3 id="细节-1-向前看-最长匹配-maximal-munch" tabindex="-1"><a class="header-anchor" href="#细节-1-向前看-最长匹配-maximal-munch" aria-hidden="true">#</a> 细节 1：向前看 + 最长匹配（maximal munch）</h3><p>为什么处理 <code>&gt;=</code> 要 <code>peek</code> 下一个字符？因为不偷看，就会把 <code>&gt;=</code> 错切成 <code>&gt;</code> 和 <code>=</code> 两个 token。规则是：<strong>尽量凑出最长的合法符号</strong>。这叫 <em>maximal munch</em>。<code>===</code>、<code>!=</code>、<code>&amp;&amp;</code> 同理。</p><h3 id="细节-2-关键字-先读完整个词-再查表" tabindex="-1"><a class="header-anchor" href="#细节-2-关键字-先读完整个词-再查表" aria-hidden="true">#</a> 细节 2：关键字&quot;先读完整个词，再查表&quot;</h3><p>看 <code>readWord</code>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">int</span> <span class="token function">readWord</span><span class="token punctuation">(</span><span class="token class-name">String</span> s<span class="token punctuation">,</span> <span class="token keyword">int</span> pos<span class="token punctuation">,</span> <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Token</span><span class="token punctuation">&gt;</span></span> tokens<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">int</span> start <span class="token operator">=</span> pos<span class="token punctuation">;</span>
    <span class="token keyword">while</span> <span class="token punctuation">(</span>pos <span class="token operator">&lt;</span> s<span class="token punctuation">.</span><span class="token function">length</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&amp;&amp;</span> <span class="token class-name">Character</span><span class="token punctuation">.</span><span class="token function">isLetterOrDigit</span><span class="token punctuation">(</span>s<span class="token punctuation">.</span><span class="token function">charAt</span><span class="token punctuation">(</span>pos<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span> pos<span class="token operator">++</span><span class="token punctuation">;</span>
    <span class="token class-name">String</span> word <span class="token operator">=</span> s<span class="token punctuation">.</span><span class="token function">substring</span><span class="token punctuation">(</span>start<span class="token punctuation">,</span> pos<span class="token punctuation">)</span><span class="token punctuation">;</span>          <span class="token comment">// 先把整个词读出来</span>
    <span class="token class-name">Type</span> t <span class="token operator">=</span> <span class="token keyword">switch</span> <span class="token punctuation">(</span>word<span class="token punctuation">)</span> <span class="token punctuation">{</span>                          <span class="token comment">// 再判断是不是关键字</span>
        <span class="token keyword">case</span> <span class="token string">&quot;and&quot;</span> <span class="token operator">-&gt;</span> <span class="token class-name">Type</span><span class="token punctuation">.</span><span class="token constant">AND</span><span class="token punctuation">;</span>
        <span class="token keyword">case</span> <span class="token string">&quot;or&quot;</span>  <span class="token operator">-&gt;</span> <span class="token class-name">Type</span><span class="token punctuation">.</span><span class="token constant">OR</span><span class="token punctuation">;</span>
        <span class="token keyword">default</span>    <span class="token operator">-&gt;</span> <span class="token class-name">Type</span><span class="token punctuation">.</span><span class="token constant">IDENT</span><span class="token punctuation">;</span>                     <span class="token comment">// 不是关键字 → 普通标识符</span>
    <span class="token punctuation">}</span><span class="token punctuation">;</span>
    tokens<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Token</span><span class="token punctuation">(</span>t<span class="token punctuation">,</span> word<span class="token punctuation">,</span> start<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> pos<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>为什么不能&quot;一看到 a-n-d 就判定关键字&quot;？因为变量名 <code>android</code> 会被错切成 <code>and</code> + <code>roid</code>。<strong>必须先读完整个词（最长匹配），再回头查它是不是关键字。</strong> 关键字和普通标识符走的是同一条读取路径，只是最后查了一次表。</p><h3 id="细节-3-跳过空白-移动指针-不是删除" tabindex="-1"><a class="header-anchor" href="#细节-3-跳过空白-移动指针-不是删除" aria-hidden="true">#</a> 细节 3：&quot;跳过空白&quot; = 移动指针，不是删除</h3><p>注意循环里跳空白只是 <code>pos++</code>，<strong>原字符串一个字都没改</strong>——我们只是把&quot;读取光标&quot;往前挪，越过没用的字符。注释也是同理（找到注释结尾，把 <code>pos</code> 一跳跳过去）。而且这件事是<strong>和切词交织</strong>进行的：每圈先跳空白、再读一个 token，不是先单独跑一遍把空格清光。</p><h3 id="细节-4-value-不一定等于源码原文" tabindex="-1"><a class="header-anchor" href="#细节-4-value-不一定等于源码原文" aria-hidden="true">#</a> 细节 4：value 不一定等于源码原文</h3><p><code>&quot;true&quot;</code> 经过 <code>readString</code> 切出来，value 是 <code>true</code>——<strong>引号没了</strong>：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">int</span> <span class="token function">readString</span><span class="token punctuation">(</span><span class="token class-name">String</span> s<span class="token punctuation">,</span> <span class="token keyword">int</span> pos<span class="token punctuation">,</span> <span class="token class-name">List</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">Token</span><span class="token punctuation">&gt;</span></span> tokens<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">int</span> start <span class="token operator">=</span> pos<span class="token operator">++</span><span class="token punctuation">;</span> <span class="token comment">// 跳过开引号</span>
    <span class="token class-name">StringBuilder</span> sb <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">StringBuilder</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">while</span> <span class="token punctuation">(</span>pos <span class="token operator">&lt;</span> s<span class="token punctuation">.</span><span class="token function">length</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&amp;&amp;</span> s<span class="token punctuation">.</span><span class="token function">charAt</span><span class="token punctuation">(</span>pos<span class="token punctuation">)</span> <span class="token operator">!=</span> <span class="token char">&#39;&quot;&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span>s<span class="token punctuation">.</span><span class="token function">charAt</span><span class="token punctuation">(</span>pos<span class="token punctuation">)</span> <span class="token operator">==</span> <span class="token char">&#39;\\\\&#39;</span><span class="token punctuation">)</span> pos<span class="token operator">++</span><span class="token punctuation">;</span>   <span class="token comment">// 处理转义：\\&quot; 只保留 &quot;</span>
        sb<span class="token punctuation">.</span><span class="token function">append</span><span class="token punctuation">(</span>s<span class="token punctuation">.</span><span class="token function">charAt</span><span class="token punctuation">(</span>pos<span class="token operator">++</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    pos<span class="token operator">++</span><span class="token punctuation">;</span> <span class="token comment">// 跳过闭引号</span>
    tokens<span class="token punctuation">.</span><span class="token function">add</span><span class="token punctuation">(</span><span class="token keyword">new</span> <span class="token class-name">Token</span><span class="token punctuation">(</span><span class="token class-name">Type</span><span class="token punctuation">.</span><span class="token constant">STRING</span><span class="token punctuation">,</span> sb<span class="token punctuation">.</span><span class="token function">toString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> start<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// value 是去引号、解转义后的内容</span>
    <span class="token keyword">return</span> pos<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>编译原理里把这两件事分开叫：</p><ul><li><strong>lexeme（词素）</strong>：源码里原始匹配到的字符（<code>&quot;true&quot;</code> 连引号）。</li><li><strong>token 的 value/属性</strong>：携带的语义值，<strong>可能是加工后的</strong>（去引号、解转义；数字常直接存解析后的数值）。</li></ul><p>两者<strong>不一定相等</strong>——这是个很多人忽略的点。</p><h2 id="六、还有一个常被自己补、不来自原文的-token-eof" tabindex="-1"><a class="header-anchor" href="#六、还有一个常被自己补、不来自原文的-token-eof" aria-hidden="true">#</a> 六、还有一个常被自己补、不来自原文的 token：EOF</h2><p>循环结束后我们手动 <code>tokens.add(EOF)</code>。它在原文里<strong>没有对应字符</strong>，纯粹是给 parser 的一个&quot;输入到头了&quot;的哨兵信号，省得 parser 每次去判断&quot;还有没有下一个 token、会不会越界&quot;。</p><h2 id="七、一个真实的边界-bug-自查代码的眼光" tabindex="-1"><a class="header-anchor" href="#七、一个真实的边界-bug-自查代码的眼光" aria-hidden="true">#</a> 七、一个真实的边界 bug（自查代码的眼光）</h2><p>处理行注释 <code>//</code> 时，常见写法是 <code>indexOf(&#39;\\n&#39;)</code> 找行尾。但它只认 <code>\\n</code>：</p><ul><li>Unix <code>\\n</code> ✓</li><li>Windows <code>\\r\\n</code> ✓（<code>\\r</code> 在被跳过的区间里一起吞掉）</li><li>老 Mac 纯 <code>\\r</code> ✗ —— 找不到 <code>\\n</code>，会把整行后面全吞到文件末尾。</li></ul><p>虽然纯 <code>\\r</code> 已基本绝迹，但<strong>能主动指出这种边界，恰恰是工程成熟度的体现</strong>。</p><h2 id="八、那我还要手写吗-antlr4-了解一下" tabindex="-1"><a class="header-anchor" href="#八、那我还要手写吗-antlr4-了解一下" aria-hidden="true">#</a> 八、那我还要手写吗？ANTLR4 了解一下</h2><p>上面这些（切词、向前看、关键字查表），其实 <strong>ANTLR4 这类&quot;解析器生成器&quot;能帮你自动生成</strong>——你只写一份 <code>.g4</code> 文法声明语言长什么样，它吐出 lexer + parser。</p><p>那为什么还讲手写？因为：</p><ol><li><strong>懂手写，才真懂 ANTLR4 自动生成的是什么</strong>，不是把它当黑盒。</li><li>工业级编译器（GCC、Clang）很多<strong>反而手写递归下降</strong>，图的是更好的报错和控制力。</li><li>取舍是：<strong>从零造一门干净的新 DSL → 用 ANTLR4 省事；解析固定庞大的旧语言、追求极致报错 → 手写。</strong></li></ol><h2 id="小结" tabindex="-1"><a class="header-anchor" href="#小结" aria-hidden="true">#</a> 小结</h2><p>词法分析没那么玄，它就是&quot;把字符切成词&quot;的一个左到右扫描循环。真正的功夫在那几个细节里：<strong>最长匹配、关键字先读后查、跳空白是移指针、value≠源文、哨兵 EOF、跨系统换行边界</strong>。把这几个点说清楚，你对编译器前端的理解就已经超过&quot;会用工具&quot;的层次了。</p><p>下一篇我会讲第二步——<strong>语法分析</strong>：这些扁平的 token，是怎么被组装成一棵 AST 树的，以及&quot;递归下降&quot;怎么用函数调用层级实现运算符优先级。</p>`,49);function k(r,d){return t(),p("div",null,[l,u,o(" more "),i])}const g=a(c,[["render",k],["__file","03lexical_analysis.html.vue"]]);export{g as default};
